const u32 mc_26_3_state_count = ARRAY_LEN(mc_26_3_state_to_block);

b8 mc_26_3_block_exists(block_id id)
{
	return id < mc_26_3_block_count && mc_26_3_block_valid[id];
}

const block_info *mc_26_3_get_block_info(block_id id)
{
	if (!mc_26_3_block_exists(id)) return NULL;
	return &mc_26_3_blocks[id];
}

const char *mc_26_3_get_block_name(block_id id)
{
	if (!mc_26_3_block_exists(id)) return NULL;
	return mc_26_3_block_names[id];
}

b8 mc_26_3_state_exists(block_state_id state)
{
	return state < mc_26_3_state_count && mc_26_3_state_to_block[state] != BLOCK_INVALID_ID;
}

block_id mc_26_3_get_block_from_state(block_state_id state)
{
	if (!mc_26_3_state_exists(state)) return BLOCK_INVALID_ID;
	return mc_26_3_state_to_block[state];
}
